//www.code-corey.com\\"}]}"],["meta",{"property":"og:url","content":"https://www.code-corey.com/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF.html"}],["meta",{"property":"og:site_name","content":"Corey 知识库"}],["meta",{"property":"og:title","content":"虚拟化技术"}],["meta",{"property":"og:description","content":"虚拟化技术 一、计算机系统虚拟化定义 1.1 物理机向虚拟机演进过程 当物理机资源足够某一应用使用，并有多余的富余时，可以把多余的资源提供给其它的应用使用，这时就需要一种计算资源“打包技术”，2001..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://www.code-corey.com/云原生/foundation/foundation-02-虚拟化技术/image-20220110200045146.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-14T02:04:51.000Z"}],["meta",{"property":"article:tag","content":"课程笔记"}],["meta",{"property":"article:tag","content":"云原生"}],["meta",{"property":"article:tag","content":"云原生基础"}],["meta",{"property":"article:published_time","content":"2026-08-13T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-14T02:04:51.000Z"}]]},"git":{"createdTime":1786673091000,"updatedTime":1786673091000,"contributors":[{"name":"chengongyi","username":"chengongyi","email":"2363613998@qq.com","commits":1,"url":"https://github.com/chengongyi"},{"name":"Cursor","username":"Cursor","email":"cursoragent@cursor.com","commits":1,"url":"https://github.com/Cursor"}]},"readingTime":{"minutes":11.79,"words":3538},"filePathRelative":"云原生/foundation/foundation-02-虚拟化技术.md","excerpt":"<blockquote>\\n<p><strong>云原生基础 · 第 2 篇</strong></p>\\n<p>来源课程笔记整理优化；插图已迁入博客静态目录。</p>\\n</blockquote>\\n<hr>\\n<h1>虚拟化技术</h1>\\n<h1>一、计算机系统虚拟化定义</h1>\\n<h2>1.1 物理机向虚拟机演进过程</h2>\\n<p>当物理机资源足够某一应用使用，并有多余的富余时，可以把多余的资源提供给其它的应用使用，这时就需要一种计算资源“打包技术”，2001年vmware公司提出来虚拟机，即在一台物理机上运行多个虚拟机，让不同或相同的应用使用虚拟机运行，这就达到了共享一台物理机计算资源的方式。</p>"}`),a={name:`foundation-02-虚拟化技术.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<blockquote><p><strong>云原生基础 · 第 2 篇</strong></p><p>来源课程笔记整理优化；插图已迁入博客静态目录。</p></blockquote><hr><h1 id="虚拟化技术" tabindex="-1"><a class="header-anchor" href="#虚拟化技术"><span>虚拟化技术</span></a></h1><h1 id="一、计算机系统虚拟化定义" tabindex="-1"><a class="header-anchor" href="#一、计算机系统虚拟化定义"><span>一、计算机系统虚拟化定义</span></a></h1><h2 id="_1-1-物理机向虚拟机演进过程" tabindex="-1"><a class="header-anchor" href="#_1-1-物理机向虚拟机演进过程"><span>1.1 物理机向虚拟机演进过程</span></a></h2><p>当物理机资源足够某一应用使用，并有多余的富余时，可以把多余的资源提供给其它的应用使用，这时就需要一种计算资源“打包技术”，2001年vmware公司提出来虚拟机，即在一台物理机上运行多个虚拟机，让不同或相同的应用使用虚拟机运行，这就达到了共享一台物理机计算资源的方式。</p><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220110200045146.png" alt="image-20220110200045146" loading="lazy"></p><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220110200109732.png" alt="image-20220110200109732" loading="lazy"></p><h2 id="_1-2-计算机系统虚拟化定义" tabindex="-1"><a class="header-anchor" href="#_1-2-计算机系统虚拟化定义"><span>1.2 计算机系统虚拟化定义</span></a></h2><p>计算机系统虚拟化就是对计算机资源的抽像。在物理机中创建软件或虚拟表示形式的应用、服务器、存储和网络，以减少 IT 开销，同时提高效率和敏捷性。</p><p>虚拟化可以提高 IT 敏捷性、灵活性和可扩展性，同时大幅节约成本。更高的工作负载移动性、更高的性能和资源可用性、自动化运维 - 这些都是虚拟化的优势，虚拟化技术可以使 IT 部门更轻松地进行管理以及降低拥有成本和运维成本。</p><h1 id="二、虚拟化技术分类" tabindex="-1"><a class="header-anchor" href="#二、虚拟化技术分类"><span>二、虚拟化技术分类</span></a></h1><h2 id="_2-1-虚拟化管理程序-hypervisor-vmm" tabindex="-1"><a class="header-anchor" href="#_2-1-虚拟化管理程序-hypervisor-vmm"><span>2.1 虚拟化管理程序 Hypervisor（VMM）</span></a></h2><p>一种运行在物理机和虚拟机操作系统之间的中间<mark>软件层</mark>，可以允许多个操作系统和应用共享硬件，即虚拟机监视器，也可称之为VMM。</p><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220110155353456.png" alt="image-20220110155353456" loading="lazy"></p><h2 id="_2-2-虚拟化管理程序-hypervisors作用" tabindex="-1"><a class="header-anchor" href="#_2-2-虚拟化管理程序-hypervisors作用"><span>2.2 虚拟化管理程序 Hypervisors作用</span></a></h2><p>Hypervisor是所有虚拟化技术的核心。 非中断地支持多工作负载迁移的能力是Hypervisor的基本功能。</p><p>Hypervisors是一种在虚拟环境中的“元”操作系统。他们可以访问服务器上包括磁盘和内存在内的所有物理设备。Hypervisors不但协调着这些硬件资源的访问，而且在各个虚拟机之间施加防护。当服务器启动并执行Hypervisor时，它会加载所有虚拟机客户端的操作系统同时会分配给每一台虚拟机适量的内存，CPU，网络和磁盘。</p><h2 id="_2-3-虚拟化管理程序hypervisors分类" tabindex="-1"><a class="header-anchor" href="#_2-3-虚拟化管理程序hypervisors分类"><span>2.3 虚拟化管理程序Hypervisors分类</span></a></h2><p>目前市场上各种x86 管理程序(hypervisor)的架构存在差异，三个最主要的架构类别包括：</p><h3 id="_2-3-1-半虚拟化-hypervisor-type-i" tabindex="-1"><a class="header-anchor" href="#_2-3-1-半虚拟化-hypervisor-type-i"><span>2.3.1 半虚拟化（Hypervisor Type I）</span></a></h3><p>虚拟机直接运行在系统硬件上，创建硬件全仿真实例，被称为“裸机”型。<br> 裸机型在虚拟化中Hypervisor直接管理调用硬件资源，不需要底层操作系统，也可以将Hypervisor看作一个很薄的操作系统。这种方案的性能处于主机虚拟化与操作系统虚拟化之间。</p><p>例如：Xen</p><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220110194319016.png" alt="image-20220110194319016" loading="lazy"></p><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220110194348034.png" alt="image-20220110194348034" loading="lazy"></p><h3 id="_2-3-2-硬件辅助全虚拟化-hypervisortyep-ii" tabindex="-1"><a class="header-anchor" href="#_2-3-2-硬件辅助全虚拟化-hypervisortyep-ii"><span>2.3.2 硬件辅助全虚拟化(HypervisorTyep II)</span></a></h3><p>虚拟机运行在传统操作系统(HOST OS)上，同样创建的是硬件全仿真实例，被称为“托管（宿主）”型。托管型/主机型Hypervisor运行在基础操作系统上，构建出一整套虚拟硬件平台（CPU/Memory/Storage/Adapter），使用者根据需要安装新的操作系统和应用软件，底层和上层的操作系统可以完全无关化，如Windows运行Linux操作系统。主机虚拟化中VM的应用程序调用硬件资源时需要经过:VM内核-&gt;Hypervisor-&gt;主机内核，因此相对来说，性能是三种虚拟化技术中最差的。</p><p>例如：kvm</p><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220110194527729.png" alt="image-20220110194527729" loading="lazy"></p><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220110194550287.png" alt="image-20220110194550287" loading="lazy"></p><h3 id="_2-3-3-软件全虚拟化-hypervisor-type-iii" tabindex="-1"><a class="header-anchor" href="#_2-3-3-软件全虚拟化-hypervisor-type-iii"><span>2.3.3 软件全虚拟化(Hypervisor Type III)</span></a></h3><p>所谓的软件全虚拟化，即非硬件辅助全虚拟化，模拟CPU让VM使用，效率低，例如：QEMU</p><h3 id="_2-3-4-操作系统虚拟化" tabindex="-1"><a class="header-anchor" href="#_2-3-4-操作系统虚拟化"><span>2.3.4 操作系统虚拟化</span></a></h3><p>称为轻量级虚拟化，允许操作系统内核拥有彼此隔离和分割的多用户空间实例（instance），这些实例也被称之为容器。其是基于Linux内核中的namespace,cgroup实现</p><p>例如：LXC,Docker</p><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220110195509448.png" alt="image-20220110195509448" loading="lazy"></p><h1 id="三、虚拟化技术管理工具" tabindex="-1"><a class="header-anchor" href="#三、虚拟化技术管理工具"><span>三、虚拟化技术管理工具</span></a></h1><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220110151928337.png" alt="image-20220110151928337" loading="lazy"></p><h1 id="四、虚拟机管理工具-vmware-workstation-pro" tabindex="-1"><a class="header-anchor" href="#四、虚拟机管理工具-vmware-workstation-pro"><span>四、虚拟机管理工具 VMware Workstation pro</span></a></h1><h2 id="_4-1-安装前准备" tabindex="-1"><a class="header-anchor" href="#_4-1-安装前准备"><span>4.1 安装前准备</span></a></h2><ul><li>创建安装目录</li></ul><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220111141447039.png" alt="image-20220111141447039" loading="lazy"></p><ul><li>准备操作系统ISO镜像文件</li></ul><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220111141519483.png" alt="image-20220111141519483" loading="lazy"></p><ul><li>虚拟机软件准备</li></ul><p><img src="/%E4%BA%91%E5%8E%9F%E7%94%9F/foundation/foundation-02-%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8A%80%E6%9C%AF/image-20220111141943956.png" alt="image-20220111141943956" loading="lazy"></p><h2 id="_4-2-安装linux操作系统虚拟机" tabindex="-1"><a class="header-anchor" href="#_4-2-安装linux操作系统虚拟机"><span>4.2 安装Linux操作系统虚拟机</span></a></h2><h3 id="_4-2-1-创建虚拟机" tabindex="-1"><a class="he